t["The default value is"]="Значение по умолчанию:"
t["The enemy will automatically be considered to be Cursed if you have at least one curse enabled,\\nbut you can use this option to force it if necessary."]="Враг автоматически считается проклятым, если включено хотя бы одно проклятие,\\nно эту опцию можно использовать для принудительного включения."
t["The enemy will automatically be considered to be Unique if they are a Boss,\\nbut you can use this option to force it if necessary."]="Враг автоматически считается уникальным, если он босс,\\nно эту опцию можно использовать для принудительного включения."
