t["The program is currently running in developer"]="Программа сейчас работает в режиме"
t["The socket must be allocated on your current tree; if it isn't, the jewel is only added to your item list."]="Гнездо должно быть изучено на вашем текущем дереве; иначе самоцвет добавляется только в список предметов."
t["The stats in the sidebar are always shown in Effective DPS mode, regardless of this setting."]="Статистика на боковой панели всегда показывается в режиме эффективного DPS независимо от этой настройки."
t["The trade site will filter out listings with other currencies,\\nif anything other than \\\"Chaos Orb Equivalent\\\" is chosen and a maximum is specified."]="Торговый сайт отфильтрует предложения с другими валютами,\\nесли выбрано что-то кроме «эквивалента Сфер хаоса» и указан максимум."
t["The tree has been converted to"]="Дерево преобразовано в"
t["The trigger needs to be triggered for any skill to be triggered."]="Для срабатывания любого умения необходимо сработать триггеру."
t["This Items Implicits Cannot Be Changed"]="Неизменяемые неявные модификаторы этого предмета"
t["This also implies that the enemy is"]="Это также подразумевает, что враг"
t["This also implies that you Totems have Hit Recently."]="Это также подразумевает, что ваши Тотемы недавно наносили удар."
t["This also implies that you are"]="Это также подразумевает, что вы"
t["This also implies that you are Poisoned."]="Это также подразумевает, что вы отравлены."
t["This also implies that you are channelling"]="Это также подразумевает, что вы направляете"
t["This also implies that you have Blocked Recently."]="Это также подразумевает, что вы недавно блокировали."
t["This also implies that you have Hit Recently."]="Это также подразумевает, что вы недавно наносили удар."
t["This also implies that you have Killed Recently."]="Это также подразумевает, что вы недавно убивали."
t["This also implies that you have Suppressed Recently."]="Это также подразумевает, что вы недавно подавляли."
t["This also implies that you have a Totem summoned.\\nThis will affect all 'per Summoned Totem' modifiers, even for non-Totem skills."]="Это также подразумевает, что у вас есть призванный Тотем.\\nЭто повлияет на все модификаторы «за призванный Тотем», даже для умений без Тотемов."
t["This also implies that you have been Hit Recently."]="Это также подразумевает, что по вам недавно наносили удар."
t["This also implies that you have killed and taunted recently."]="Это также подразумевает, что вы недавно убивали и провоцировали."
t["This also implies that you have used a Skill Recently."]="Это также подразумевает, что вы недавно использовали умение."
t["This also implies that you have used a Skill Recently.\\nYou will automatically be considered to have Attacked Recently if your main skill is an attack,\\nbut you can use this option to force it if necessary."]="Это также подразумевает, что вы недавно использовали умение.\\nВы автоматически считаетесь недавно атаковавшим, если ваше основное умение — атака,\\nно эту опцию можно использовать для принудительного включения."
t["This also implies that you have used a Skill Recently.\\nYou will automatically be considered to have Cast a Spell Recently if your main skill is a spell,\\nbut you can use this option to force it if necessary."]="Это также подразумевает, что вы недавно использовали умение.\\nВы автоматически считаетесь недавно сотворившим чары, если ваше основное умение — чары,\\nно эту опцию можно использовать для принудительного включения."
t["This also implies that you have used a Skill Recently.\\nYou will automatically be considered to have used a Minion skill Recently if your main skill is a Minion skill,\\nbut you can use this option to force it if necessary."]="Это также подразумевает, что вы недавно использовали умение.\\nВы автоматически считаетесь недавно использовавшим умение приспешника, если ваше основное умение — умение приспешника,\\nно эту опцию можно использовать для принудительного включения."
t["This also implies that you have used a Skill Recently.\\nYou will automatically be considered to have used a Movement skill Recently if your main skill is a movement skill,\\nbut you can use this option to force it if necessary."]="Это также подразумевает, что вы недавно использовали умение.\\nВы автоматически считаетесь недавно использовавшим умение перемещения, если ваше основное умение — умение перемещения,\\nно эту опцию можно использовать для принудительного включения."
t["This also implies that you have used a Skill Recently.\\nYou will automatically be considered to have used a Vaal skill Recently if your main skill is a Vaal skill,\\nbut you can use this option to force it if necessary."]="Это также подразумевает, что вы недавно использовали умение.\\nВы автоматически считаетесь недавно использовавшим умение Ваал, если ваше основное умение — умение Ваал,\\nно эту опцию можно использовать для принудительного включения."
t["This also implies that your Minions have Killed Recently."]="Это также подразумевает, что ваши приспешники недавно убивали."
t["This also implies that your Skills have Crit Recently."]="Это также подразумевает, что ваши умения недавно наносили критический удар."
t["This also implies that your Totems have Killed Recently."]="Это также подразумевает, что ваши Тотемы недавно убивали."
t["This also implies you have 'Consumed a corpse Recently'"]="Это также подразумевает, что вы недавно поглотили труп"
t["This also implies you have 'Used a Warcry Recently', 'Used a Warcry in the past 8 seconds', and 'Used a Skill Recently'"]="Это также подразумевает, что вы недавно использовали боевой клич, использовали боевой клич за последние 8 секунд и недавно использовали умение"
t["This applies -10%"]="Применяется -10%"
