t["This multiplies the damage of a given skill in pvp, for instance any with damage multiplier specific to pvp (from skill or support or item like sire of shards)"]="Умножает урон умения в PvP, например для умений с множителем урона, специфичным для PvP (от умения, поддержки или предмета вроде Повелителя осколков)"
