t["This option allows you to override the default calculation for the number of Empty White Sockets.\\nThe default calculation assumes enabled gems in skill socket groups fill the item in socket order disregarding gem colour.\\nLeave blank for default calculation."]="Эта опция позволяет переопределить расчёт по умолчанию для числа пустых белых гнёзд.\\nПо умолчанию считается, что включённые камни в группах гнёзд умений заполняют предмет по порядку гнёзд, независимо от цвета камня.\\nОставьте пустым для расчёта по умолчанию."
