t["Your Absolution Skill Damage will not be scaled with Count setting.\\nBy default it multiplies both minion count and skill hit count which leads to incorrect\\nTotal DPS calculation since Absolution cannot inherently shotgun.\\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"]="Урон умения «Отпущение» не будет масштабироваться настройкой «Количество».\\nПо умолчанию она умножает и число приспешников, и число ударов умения, что даёт неверный\\nобщий DPS, так как «Отпущение» не может бить картечью.\\nНе включайте, если используете поддержку Чарного тотема, Каскада чар или похожие поддержки"
