t["Your Fire Resistance"]="Ваше сопротивление огню"
t["Your Holy Strike Skill Damage will not be scaled with Count setting.\\nBy default it multiplies both minion count and skill hit count which leads to incorrect\\nTotal DPS calculation since Holy Strike cannot inherently shotgun."]="Урон умения Holy Strike не будет масштабироваться настройкой Count.\\nПо умолчанию она умножает и число приспешников, и число попаданий умения, что даёт неверный\\nобщий DPS, так как Holy Strike не может бить дробью."
