t["\\n+5 to Devotion"]="\\n+5 к преданности"
t["\\n10% increased Action Speed\\nBuff affects the player and allies\\nBuff has a base duration of 8s with a 10s Cooldown"]="\\n10% повышение скорости действий\\nЭффект действует на игрока и союзников\\nБазовая длительность эффекта 8 с, перезарядка 10 с"
t["\\n10% increased Action Speed\\nBuff affects the player, allies and enemies in a small radius\\nBuff has a base duration of 8s with a 20s Cooldown"]="\\n10% повышение скорости действий\\nЭффект действует на игрока, союзников и врагов в малом радиусе\\nБазовая длительность эффекта 8 с, перезарядка 20 с"
t["\\n15% faster start of Energy Shield Recharge, \\nChannelling Spells deal 5% more Damage and \\nChannelling Spells have 10% more Cost\\nMaximum 10 stacks"]="\\n15% более быстрое начало восстановления энергетического щита, \\nКанализируемые чары наносят на 5% больше урона и \\nКанализируемые чары требуют на 10% больше затрат\\nМаксимум 10 зарядов"
t["\\n20% increased Flask Charges gained\\n10% increased effect of Flasks"]="\\n20% повышение получаемых зарядов фляги\\n10% повышение эффекта фляг"
t["\\nAdding this mod will give"]="\\nДобавление этого свойства даст"
t["\\nAuthorization is invalid. Please Re-Log and reset"]="\\nАвторизация недействительна. Войдите заново и сбросьте"
t["\\nAverage: Averages out Warcry usage with cast time, attack speed and warcry cooldown.\\nMax Hit: Shows maximum hit for lining up all warcries."]="\\nСреднее: усредняет использование кличей с учётом времени сотворения, скорости атаки и перезарядки кличей.\\nМакс. удар: показывает максимальный удар при совмещении всех кличей."
t["\\nAverage: Averages the effect based on Pact uptime.\\nMax Hit: Applies the full effect to one Empowered spell."]="\\nСреднее: усредняет эффект по времени действия пакта.\\nМакс. удар: применяет полный эффект к одним усиленным чарам."
t["\\nCheck your internet connectivity.\\nIf you are using a proxy, specify it in Options."]="\\nПроверьте подключение к интернету.\\nЕсли вы используете прокси, укажите его в настройках."
t["\\nCurrent Path"]="\\nТекущий путь"
t["\\nEnemies Deal 30% Increased Damage\\nEnemies take 80% Less Damage"]="\\nВраги наносят на 30% больше урона\\nВраги получают на 80% меньше урона"
t["\\nHas a default cap of 20 stacks."]="\\nПо умолчанию максимум 20 зарядов."
t["\\nIf this location is managed by OneDrive, navigate to that folder and manually try"]="\\nЕсли это место управляется OneDrive, перейдите в эту папку и попробуйте вручную"
t["\\nIf updating while inside a build, please re-load the build after saving."]="\\nЕсли обновление идёт внутри билда, загрузите билд заново после сохранения."
t["\\nMake sure the save folder exists and is writable."]="\\nУбедитесь, что папка сохранения существует и доступна для записи."
t["\\nPlease re-authenticate"]="\\nПройдите повторную аутентификацию"
t["\\nScroll Up = Move right\\nScroll Down = Move left"]="\\nПрокрутка вверх = вправо\\nПрокрутка вниз = влево"
t["\\nThis cannot be undone."]="\\nЭто нельзя отменить."
t["\\nYou cannot delete this group, but it will disappear if you lose the above sources."]="\\nЭту группу нельзя удалить, но она исчезнет, если вы потеряете указанные выше источники."
t["\\nYou lose 10"]="\\nВы теряете 10"
t["\\nYou will automatically be considered to be on Full"]="\\nВы автоматически считаетесь находящимся на полном"
t["\\n\\t1% increased Movement Speed per 20 Rampage\\n\\t2% increased Damage per 20 Rampage\\nYou lose Rampage if you do not get a Kill within 5 seconds."]="\\n\\t1% повышение скорости передвижения за каждые 20 Буйства\\n\\t2% повышение урона за каждые 20 Буйства\\nВы теряете Буйство, если не совершили убийство в течение 5 секунд."
t["\\n\\t10% increased Effect of Curses\\n\\t100% increased chance to be Critically Hit"]="\\n\\t10% повышение эффекта проклятий\\n\\t100% повышение шанса получить критический удар"
t["\\n\\t10% more Minion Damage\\n\\t10% increased Minion Movement Speed\\n\\t10% increased Minion Attack and Cast Speed"]="\\n\\t10% больше урона приспешников\\n\\t10% повышение скорости передвижения приспешников\\n\\t10% повышение скорости атаки и сотворения приспешников"
t["\\n\\t100% increased Damage\\n\\t25% increased Attack, Cast and Movement Speed\\n\\t10% additional Physical Damage Reduction"]="\\n\\t100% повышение урона\\n\\t25% повышение скорости атаки, сотворения и передвижения\\n\\t10% дополнительное снижение физического урона"
t["\\n\\t100% increased Physical Damage\\n\\t10% increased Action Speed\\n\\tHits ignore Enemy Physical Damage Reduction\\n\\tCannot be Stunned"]="\\n\\t100% повышение физического урона\\n\\t10% повышение скорости действий\\n\\tУдары игнорируют снижение физического урона врага\\n\\tНевозможно оглушить"
t["\\n\\t100% increased maximum"]="\\n\\t100% повышение максимума"
t["\\n\\t15% Chance to Avoid all Damage from Hits\\n\\t30% increased Movement Speed\\nThe effect of Elusive decays over time."]="\\n\\t15% шанс избежать всего урона от ударов\\n\\t30% повышение скорости передвижения\\nЭффект Неуловимости со временем спадает."
t["\\n\\t20% increased"]="\\n\\t20% повышение"
t["\\n\\t30% increased Damage Taken\\n\\tDeal 30% less Damage"]="\\n\\t30% повышение получаемого урона\\n\\tВы наносите на 30% меньше урона"
t["\\n\\t4% inc Damage Taken per stack\\n\\t2% reduced Action Speed per stack\\n\\t10% reduced"]="\\n\\t4% повышение получаемого урона за заряд\\n\\t2% снижение скорости действий за заряд\\n\\t10% снижение"
t["\\n\\t5% increased Attack Speed\\n\\t5% increased Cast Speed\\n\\t1% increased character size per stack."]="\\n\\t5% повышение скорости атаки\\n\\t5% повышение скорости сотворения чар\\n\\t1% повышение размера персонажа за заряд."
t["\\n\\t50% increased maximum"]="\\n\\t50% повышение максимума"
t["\\n\\t75% more Elemental Damage\\n\\t25% less Elemental Damage taken"]="\\n\\t75% больше урона от стихий\\n\\t25% меньше получаемого урона от стихий"
t["\\n\\tAverage: damage is based on the average application, including both crits and non-crits\\n\\tCrits Only: damage is based solely on Ailments inflicted with crits"]="\\n\\tСреднее: урон считается по среднему применению, включая крит и некрит\\n\\tТолько крит: урон считается только по состояниям, наложенным критом"
t["\\n\\tAverage: damage is based on the average application\\n\\tMax Effect: damage is based on maximum effect"]="\\n\\tСреднее: урон считается по среднему применению\\n\\tМакс. эффект: урон считается по максимальному эффекту"
t["\\n\\tAverage: uses the Average of all typed damage types (except Damage Over Time and Untyped)\\n\\nIf a specific damage type is selected, that will be the only type used."]="\\n\\tСреднее: используется среднее по всем типам урона (кроме урона со временем и без типа)\\n\\nЕсли выбран конкретный тип урона, будет использоваться только он."
t["\\n\\tDeal 10% less Damage\\n\\t10% reduced Action Speed"]="\\n\\tВы наносите на 10% меньше урона\\n\\tСнижение скорости действий на 10%"
t["\\n\\tEroding Touch: 6% inc Damage Taken per stack\\n\\tParalysing Touch: 6% reduced Action Speed per stack\\n\\tDiluting Touch: 9% reduced Flask charges gained and 9% reduced Flask Effect per stack\\n\\tWasting Touch: 9% reduced"]="\\n\\tЕдкое касание: 6% повышение получаемого урона за заряд\\n\\tПарализующее касание: 6% снижение скорости действий за заряд\\n\\tРазбавляющее касание: 9% снижение получаемых зарядов фляги и 9% снижение эффекта фляг за заряд\\n\\tИстощающее касание: 9% снижение"
t["\\n\\tMinimum: does not include burst regen\\n\\tAverage: includes burst regen, averaged based on uptime\\n\\tBurst: includes full burst regen"]="\\n\\tМинимум: без учёта всплеска восстановления\\n\\tСреднее: с учётом всплеска восстановления, усреднённого по времени действия\\n\\tВсплеск: с учётом полного всплеска восстановления"
t["\\n\\tMinimum: does not include chances\\n\\tAverage: includes chance gains, averaged based on uptime\\n\\tMaximum: treats all chances as certain"]="\\n\\tМинимум: без учёта шансов\\n\\tСреднее: с учётом шансов, усреднённых по времени действия\\n\\tМаксимум: все шансы считаются гарантированными"
t["\\n\\tMinimum: never Defend with Double Armour\\n\\tAverage: Damage Reduction from Defending with Double Armour is proportional to chance\\n\\tMaximum: always Defend with Double Armour\\nThis setting has no effect if you have 100% chance to Defend with Double Armour."]="\\n\\tМинимум: никогда не защищаетесь с двойной бронёй\\n\\tСреднее: снижение урона от защиты с двойной бронёй пропорционально шансу\\n\\tМаксимум: всегда защищаетесь с двойной бронёй\\nНастройка не действует, если у вас 100% шанс защититься с двойной бронёй."
